mapper.select:
SELECT
  class,
  study
FROM
  ttokssaemdb.studyplan
WHERE
  memberid = #{memberid}
  AND plandate = #{plandate}

mapper.delete:
DELETE FROM 
  ttokssaemdb.studyplan
WHERE
  memberid = #{memberid}
  AND plandate = #{plandate}

mapper.select:
SELECT count(*) totcnt FROM( SELECT studyplan.plandate FROM ttokssaemdb.studyplan studyplan WHERE DATE(studyplan.plandate) <> CURRENT_DATE()
AND studyplan.memberid = #{memberid}
GROUP BY studyplan.plandate ) R1

SELECT R1.* FROM( SELECT studyplan.plandate, COUNT(*) plancount, COUNT(CASE WHEN studyplan.achieveyn = 'Y' THEN 1 END) As achievecount FROM ttokssaemdb.studyplan studyplan WHERE DATE(studyplan.plandate) <> CURRENT_DATE()
AND studyplan.memberid = #{memberid}
GROUP BY studyplan.plandate ORDER BY studyplan.plandate DESC ) R1
LIMIT ${length} OFFSET ${start}
